def solve():
    n, m = map(int, input().split())

    # Edge case handling for invalid or extreme values of n and m

    total_cost = float('inf')

    visited_rows = set([0])

    for row in range(1, n + 1):
        if (n - 2) % 2 == 1:
            current_value = min(m - 2, row)
        else:
            current_value = min(n - row, m // 2)

        total_cost = min(total_cost, int(input()[0]) * m + current_value)

        # Set to keep track if the path has visited a cell
    for j in range(1, m):
        visited_rows.add(j)

    total_cost += max(-float('inf'), 6)  
    if m == n or not visited_rows:
        total_cost -= int(input()[0])

    return total_cost
